prompt.text:
Repair the following complete `solution.py`. `rank_nodes(edges, rounds=20, damping=0.85)` accepts a non-string sequence of two-item `(source, destination)` sequences whose node names are non-empty strings. Duplicate edges are meaningful. Node order is first appearance while scanning edges. Return a new dictionary in that order containing scores after exactly `rounds` updates. Start each node at `1/N`; on every update, each node receives `(1-damping)/N`, each non-sink node divides its score equally across its outgoing edges, and all sink score is divided equally among every node. Empty edges return `{}`. `rounds` must be a non-negative non-boolean integer and damping a finite real in `[0, 1]`, excluding booleans. Do not mutate or retain aliases to inputs. Return a corrected complete source file.

```python
from collections.abc import Sequence
from math import isfinite
from numbers import Real


def rank_nodes(edges, rounds=20, damping=0.85):
    if isinstance(edges, (str, bytes)) or not isinstance(edges, Sequence):
        raise TypeError("edges must be a sequence")
    if isinstance(rounds, bool) or not isinstance(rounds, int):
        raise TypeError("rounds must be an integer")
    if rounds < 0:
        raise ValueError("rounds cannot be negative")
    if isinstance(damping, bool) or not isinstance(damping, Real):
        raise TypeError("damping must be real")
    if not isfinite(damping) or not 0 <= damping <= 1:
        raise ValueError("damping must be finite and between zero and one")

    nodes = []
    seen = set()
    copied_edges = []
    for edge in edges:
        if isinstance(edge, (str, bytes)) or not isinstance(edge, Sequence) or len(edge) != 2:
            raise TypeError("each edge must contain two node names")
        source, destination = edge
        if not isinstance(source, str) or not isinstance(destination, str):
            raise TypeError("node names must be strings")
        if not source or not destination:
            raise ValueError("node names cannot be empty")
        copied_edges.append((source, destination))
        for node in (source, destination):
            if node not in seen:
                seen.add(node)
                nodes.append(node)

    if not nodes:
        return {}
    outgoing = {node: [] for node in nodes}
    incoming_count = {node: 0 for node in nodes}
    for source, destination in copied_edges:
        outgoing[source].append(destination)
        incoming_count[destination] += 1

    count = len(nodes)
    scores = {node: 1.0 / count for node in nodes}
    for _ in range(rounds):
        sink = sum(scores[node] for node in nodes if not outgoing[node])
        updated = {node: (1.0 - damping) / count + damping * sink / count for node in nodes}
        for source in nodes:
            if outgoing[source]:
                share = damping * scores[source] / max(1, incoming_count[source])
                for destination in outgoing[source]:
                    updated[destination] += share
        scores = updated
    return scores
```

