import math
import unittest
from fractions import Fraction

from solution import rank_nodes


class RankNodesTests(unittest.TestCase):
    def reference(self, edges, rounds, damping):
        nodes = []
        for source, destination in edges:
            if source not in nodes:
                nodes.append(source)
            if destination not in nodes:
                nodes.append(destination)
        if not nodes:
            return {}
        outgoing = {node: [] for node in nodes}
        for source, destination in edges:
            outgoing[source].append(destination)
        count = len(nodes)
        scores = {node: 1.0 / count for node in nodes}
        for _ in range(rounds):
            sink_score = sum(scores[node] for node in nodes if not outgoing[node])
            updated = {
                node: (1.0 - damping) / count + damping * sink_score / count
                for node in nodes
            }
            for source in nodes:
                if outgoing[source]:
                    share = damping * scores[source] / len(outgoing[source])
                    for destination in outgoing[source]:
                        updated[destination] += share
            scores = updated
        return scores

    def assertScoresAlmostEqual(self, actual, expected):
        self.assertEqual(list(actual), list(expected))
        for node in expected:
            self.assertAlmostEqual(actual[node], expected[node], places=12)

    def test_empty_edges(self):
        self.assertEqual(rank_nodes([]), {})

    def test_zero_rounds_returns_uniform_scores_in_first_appearance_order(self):
        result = rank_nodes([("b", "a"), ("c", "b")], rounds=0)
        self.assertEqual(list(result), ["b", "a", "c"])
        self.assertScoresAlmostEqual(result, {"b": 1 / 3, "a": 1 / 3, "c": 1 / 3})

    def test_exact_number_of_updates_with_sink_distribution(self):
        edges = [("a", "b")]
        for rounds in [1, 2, 20]:
            with self.subTest(rounds=rounds):
                expected = self.reference(edges, rounds, 0.85)
                self.assertScoresAlmostEqual(rank_nodes(edges, rounds, 0.85), expected)
                self.assertAlmostEqual(sum(rank_nodes(edges, rounds, 0.85).values()), 1.0)

    def test_duplicate_edges_are_meaningful(self):
        edges = [("a", "b"), ("a", "b"), ("a", "c"), ("b", "a"), ("c", "a")]
        expected = self.reference(edges, 3, 0.9)
        actual = rank_nodes(edges, rounds=3, damping=0.9)
        self.assertScoresAlmostEqual(actual, expected)
        self.assertGreater(actual["b"], actual["c"])

    def test_damping_boundaries(self):
        edges = [("a", "b"), ("b", "a")]
        self.assertScoresAlmostEqual(rank_nodes(edges, 4, 0), self.reference(edges, 4, 0))
        self.assertScoresAlmostEqual(rank_nodes(edges, 4, 1), self.reference(edges, 4, 1))
        self.assertScoresAlmostEqual(
            rank_nodes(edges, 2, Fraction(1, 2)),
            self.reference(edges, 2, Fraction(1, 2)),
        )

    def test_input_is_not_mutated_or_retained(self):
        edges = [["a", "b"], ["b", "c"]]
        before = [edge[:] for edge in edges]
        result = rank_nodes(edges, rounds=2)
        self.assertEqual(edges, before)
        edges[0][0] = "changed"
        edges.append(["x", "y"])
        self.assertEqual(list(result), ["a", "b", "c"])

    def test_rejects_bad_top_level_edges(self):
        for edges in ["ab", b"ab", None, 3, (edge for edge in [])]:
            with self.subTest(edges=edges):
                with self.assertRaises(TypeError):
                    rank_nodes(edges)

    def test_rejects_malformed_edges_and_names(self):
        invalid = [
            [("a",)], [("a", "b", "c")], ["ab"],
            [(1, "b")], [("a", None)], [("", "b")], [("a", "")],
        ]
        for edges in invalid:
            with self.subTest(edges=edges):
                with self.assertRaises((TypeError, ValueError)):
                    rank_nodes(edges)

    def test_round_validation(self):
        for rounds in [True, False, 1.0, "1", None]:
            with self.subTest(rounds=rounds):
                with self.assertRaises(TypeError):
                    rank_nodes([], rounds=rounds)
        for rounds in [-1, -10]:
            with self.subTest(rounds=rounds):
                with self.assertRaises(ValueError):
                    rank_nodes([], rounds=rounds)

    def test_damping_validation(self):
        for damping in [True, False, "0.5", None, 1 + 0j]:
            with self.subTest(damping=damping):
                with self.assertRaises(TypeError):
                    rank_nodes([], damping=damping)
        for damping in [-0.01, 1.01, math.inf, -math.inf, math.nan]:
            with self.subTest(damping=damping):
                with self.assertRaises(ValueError):
                    rank_nodes([], damping=damping)


if __name__ == "__main__":
    unittest.main()

